private fun parseBatch(ixData: ByteArray, metas: List<AccountMeta>, ixProgramId: SolanaPublicKey): TokenInstruction.Batch? {
    if (!ixData.startsWithBytes(BATCH_DISCRIMINATOR) || metas.size < 0) return null
    return runCatching {
        val r = DataReader(ixData, BATCH_DISCRIMINATOR.size)
        val data = buildList { while (r.hasRemaining()) add(BatchDataItem.read(r)) }
